{
  "missing_information": [
    {
      "category": "Workflow Trigger",
      "gap": "What event or condition officially starts the summarization process after a meeting ends",
      "why_it_matters": "Automation requires a clear, detectable trigger; without it the workflow cannot be reliably initiated"
    },
    {
      "category": "Summary Creation",
      "gap": "Who creates the summary, using what method and source material",
      "why_it_matters": "Determines whether the creation step can be automated or assisted, and what inputs the system must handle"
    },
    {
      "category": "Summary Format",
      "gap": "Whether a required structure or template exists for the summary content",
      "why_it_matters": "A defined template is a prerequisite for consistent automated generation or validation of summaries"
    },
    {
      "category": "Recipient Determination",
      "gap": "How the list of email recipients is decided after each meeting",
      "why_it_matters": "Recipient logic must be encoded for automated email dispatch; manual curation is a bottleneck to automation"
    },
    {
      "category": "Review and Approval",
      "gap": "Whether the summary must be approved before sending, by whom, and how long that takes",
      "why_it_matters": "An approval gate is a distinct process step that affects timing, responsibility assignment, and automation scope"
    },
    {
      "category": "Timing and Volume",
      "gap": "Required turnaround time for sending the summary and the typical volume of meetings triggering the workflow",
      "why_it_matters": "Deadline constraints shape SLA design; volume informs scalability and prioritisation of automation effort"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What event or action officially signals that a meeting has ended and should trigger the summarization workflow — for example, the meeting ending in a calendar system, a manual action by the organizer, or something else?",
      "targets": ["Workflow Trigger"],
      "source_ids": ["C1"],
      "selection_reason": "Identifying the trigger is foundational to any automation design; C1 addresses this precisely and without overlap with other candidates"
    },
    {
      "id": "Q2",
      "question": "Who is currently responsible for producing the meeting summary, and what source material and method are used — for example, manual notes, a shared recording, or an AI-assisted transcription tool?",
      "targets": ["Summary Creation"],
      "source_ids": ["C2", "C4"],
      "selection_reason": "C2 and C4 together cover responsibility and input material, which are tightly coupled; merging them avoids two separate questions on the same creation step while C3 is subsumed"
    },
    {
      "id": "Q3",
      "question": "Is there a required format or template for the summary — for example, mandatory sections for decisions made, action items with owners, or follow-up deadlines?",
      "targets": ["Summary Format"],
      "source_ids": ["C6"],
      "selection_reason": "C6 asks this cleanly; C11 is redundant with it and is therefore not used separately"
    },
    {
      "id": "Q4",
      "question": "How is the list of email recipients determined after each meeting — is it always the attendees, a predefined distribution list, or does someone manually decide who should receive the summary?",
      "targets": ["Recipient Determination"],
      "source_ids": ["C5"],
      "selection_reason": "C5 captures the recipient logic question clearly; C8 is near-identical and is excluded to avoid duplication"
    },
    {
      "id": "Q5",
      "question": "Does the summary need to be reviewed or approved by anyone before the email is sent — and if so, who is responsible for that review and what is the typical turnaround time for their approval?",
      "targets": ["Review and Approval"],
      "source_ids": ["C7", "C10"],
      "selection_reason": "C7 and C10 address the same approval gate; merging them into one question captures both the responsible party and the timing dimension without redundancy"
    },
    {
      "id": "Q6",
      "question": "Is there a required timeframe within which the summary email must be sent after the meeting, and approximately how many meetings per week trigger this workflow?",
      "targets": ["Timing and Volume"],
      "source_ids": ["C9", "C12"],
      "selection_reason": "Deadline and volume are both operational parameters needed for SLA and scalability design; combining them keeps the question count within limit while covering a coherent operational theme"
    }
  ]
}
